with scored as (select *, sum(amount) over w_running running_amount, ntile(10) over w_recent shipping_fee_bucket from orders window w_running as (order by order_date, id rows between unbounded preceding and current row), w_recent as (partition by store_id order by shipping_fee, id)) select case when discount >= 0.34 then 'HIGH' else 'LOW' end as discount_tier, count(case when status = 'RETURNED' then 1 end) as returned_count, approx_percentile(running_amount, 0.95) as running_amount_p95, avg(running_amount) as avg_running_amount, size(collect_set(status)) as num_status from scored group by case when discount >= 0.34 then 'HIGH' else 'LOW' end order by discount_tier desc;
